import{_ as c,l as n,o as a,c as s,v as r,p as i,x as t,d as l,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"RCU 友好的结构","description":"","frontmatter":{"title":"RCU 友好的结构","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rcu-data-structures.md","filePath":"cs/rcu-data-structures.md","lastUpdated":1789023840000}'),u={name:"cs/rcu-data-structures.md"};function E(_,e,h,C,A,m){const o=n("Mermaid");return a(),s("div",null,[e[1]||(e[1]=r('<h1 id="rcu-友好的结构" tabindex="-1">RCU 友好的结构 <a class="header-anchor" href="#rcu-友好的结构" aria-label="Permalink to &quot;RCU 友好的结构&quot;">​</a></h1><div class="epigraph"><p>读者不取锁：只记已进入读侧临界区。写者复制或拼接新结构，宽限期过后再释放旧节点。</p><footer>—— 据 McKenney and Slingwine, Read-Copy Update: Using Execution History to Solve Concurrency Problems, PDCS 1998；McKenney, RCU 系列文献；[RCU 宽限期](/cs/rcu-gp) 整理</footer></div><p><a href="/cs/concurrent-hashmap">上一课</a> 的 get 仍常碰原子或桶锁。<a href="/cs/rcu-gp">RCU 宽限期</a> 已定义 GP。<a href="/cs/persistent-path-copy">路径复制</a> 提供写复制图像。本课不 Treiber。缺口是哪些结构适合 RCU：单向链表、基数树、哈希链——读者遍历，写者 <code>rcu_assign_pointer</code>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>读远多于写（路由表、配置、目录）。锁读者会互撞。RCU：读侧 <code>rcu_read_lock</code> 几乎是关抢占或记状态；写者做 copy-update，发布新指针，<code>synchronize_rcu</code> 等所有读者离开旧视图。缺口是<strong>结构必须允许「旧新并存」直到 GP</strong>：不能原地改读者正扫的字段除非小心（或只用追加）。</p><p><span class="marginnote">McKenney–Slingwine 1998。内核哈希桶、<code>list_replace_rcu</code> 是实例。用户态 urcu 同构。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>链表删除：摘指针发表，GP 后 free。更新：新节点填好，CAS 或锁下改前驱 next。树：写路径复制或 COW 根。哈希表：桶链 RCU，扩容仍难，常读锁写或分层。</p>',8)),(a(),i(p,null,{default:t(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E8%AF%BB%E8%80%85%3A%20%E6%97%A0%E9%94%81%E9%81%8D%E5%8E%86%22%5D%20--%3E%20OLD%5B%22%E5%8F%AF%E8%83%BD%E7%9C%8B%E8%A7%81%E6%97%A7%E8%8A%82%E7%82%B9%22%5D%0A%20%20W%5B%22%E5%86%99%E8%80%85%3A%20%E5%A4%8D%E5%88%B6%2F%E6%8B%BC%E6%8E%A5%22%5D%20--%3E%20PUB%5B%22%E5%8F%91%E8%A1%A8%E6%96%B0%E6%8C%87%E9%92%88%22%5D%0A%20%20PUB%20--%3E%20GP%5B%22synchronize_rcu%22%5D%0A%20%20GP%20--%3E%20FREE%5B%22%E5%86%8D%E9%87%8A%E6%94%BE%E6%97%A7%E8%8A%82%E7%82%B9%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>与 HP：RCU 读侧更轻，写侧延迟更大、要能停或异步回调。与 HAMT 持久：语义像无限版本；RCU 通常只保到 GP 的读者。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>内存屏障：发表前写节点字段。读者遍历要用 <code>rcu_dereference</code>。本课不重开调度器。分配器下一课：RCU 延迟释放会给分配器压力，与空闲链结构有关。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把内核 API 清单当正文。写多读多仍用锁或无锁表。不要用 RCU 保护任意图的随便原地改。</p><p>后课默认：读多链表/树可用 RCU 发表。分配器自身的空闲结构下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RCU 结构：读者无锁，写者发表，GP 后回收。</li><li>适合链表、某些树与哈希链；原地改受限。</li><li>下一课分配器内部空闲结构。</li><li>出处：McKenney and Slingwine, 1998；McKenney RCU 文献。</li></ul>',8))])}const B=c(u,[["render",E]]);export{f as __pageData,B as default};
